export interface UserProfile {
  id: string;
  role: 'admin' | 'user';
}

export function isUserProfile(payload: unknown): payload is UserProfile {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    'id' in payload &&
    typeof (payload as Record<string, unknown>).id === 'string' &&
    'role' in payload &&
    ['admin', 'user'].includes((payload as Record<string, unknown>).role as string)
  );
}

public sealed interface Result<T> permits Result.Success, Result.Error {
    record Success<T>(T data) implements Result<T> {}
    record Error<T>(String message) implements Result<T> {}

    static <T> String handle(Result<T> result) {
        return switch (result) {
            case Success<T> s -> "Success: " + s.data();
            case Error<T> e -> "Error: " + e.message();
        };
    }
}

namespace JWDocs.Refactoring;

/// <summary>
/// Processes customer orders and applies valid discounts.
/// </summary>
/// <param name="logger">The logging service for audit trails.</param>
/// <param name="calculator">The discount calculation engine.</param>
public class OrderProcessor(ILogger logger, IDiscountCalculator calculator)
{
    public OrderResult Process(Order order)
    {
        logger.LogInformation("Processing order {OrderId}", order.Id);
        var discount = calculator.Calculate(order);
        return new OrderResult(order.Id, order.Total - discount);
    }
}
